ValidationRule.errorConditionFormula:
RecordType.DeveloperName <> 'Chakr_Marjak' && AND( ISCHANGED(Project_Status__c), Pre_Dispatch_Clearance_Finance__c !="Yes", OR(
ISPICKVAL(Project_Status__c, "Finance Pre Dispatch"), ISPICKVAL(Project_Status__c, "Project Management Team"), ISPICKVAL(Project_Status__c, "Invoicing"), ISPICKVAL(Project_Status__c, "Dispatch Team"), ISPICKVAL(Project_Status__c, "Finance Team - Post Delivery"), ISPICKVAL(Project_Status__c, "Installation Team"), ISPICKVAL(Project_Status__c, "Final Payment"), ISPICKVAL(Project_Status__c, "Project Completed")
) )
